#!/usr/bin/env python3
"""Generate deterministic NeuroBlackwell research modules.

Usage:
  python tools/generate_missing.py --seed 20261010 --output generated
"""
from __future__ import annotations
import argparse, hashlib, json, random
from pathlib import Path

TEMPLATES={
"algebra/polynomial.py":'''"""Deterministic polynomial helpers generated by NeuroBlackwell."""

def evaluate(coefficients, x):
    result = 0.0
    for coefficient in reversed(coefficients):
        result = result * x + coefficient
    return result

def derivative(coefficients):
    return [i*c for i,c in enumerate(coefficients)][1:]
''',
"calculus/derivatives.py":'''"""Finite-difference calculus helpers."""

def central_difference(fn, x, h=1e-6):
    return (fn(x+h)-fn(x-h))/(2*h)

def second_difference(fn, x, h=1e-4):
    return (fn(x+h)-2*fn(x)+fn(x-h))/(h*h)
''',
"calculus/integral_outputs.py":'''"""Generated integral outputs and quadrature utilities."""
import math

def integrate_power(power, a=0.0, b=1.0):
    return (b**(power+1)-a**(power+1))/(power+1)

def integrate_exp(a=0.0,b=1.0):
    return math.exp(b)-math.exp(a)

def integrate_sine(a=0.0,b=math.pi):
    return -math.cos(b)+math.cos(a)

def output_suite():
    return {"int_x_0_1": integrate_power(1), "int_x2_0_1": integrate_power(2), "int_exp_0_1": integrate_exp(), "int_sin_0_pi": integrate_sine()}
''',
"calculus/integration.py":'''"""Numerical integration helpers."""

def trapezoid(fn, a, b, n=1000):
    step=(b-a)/n
    total=0.5*(fn(a)+fn(b))
    for i in range(1,n):
        total += fn(a+i*step)
    return total*step
''',
"probability/distributions.py":'''"""Small probability primitives for experiments."""
import math

def bernoulli_pmf(k,p):
    if k not in (0,1):
        return 0.0
    return p if k else 1-p

def poisson_pmf(k,lam):
    if k < 0:
        return 0.0
    return math.exp(-lam)*lam**k/math.factorial(k)
''',
"optimization/gradient_descent.py":'''"""Deterministic scalar gradient descent."""

def minimize(f, df, x0, learning_rate=0.01, steps=100):
    x=float(x0)
    for _ in range(steps):
        x -= learning_rate*df(x)
    return {"x":x,"value":f(x),"steps":steps}
''',
"benchmarks/odd_even.py":'''"""Odd/even benchmark with reproducible generated samples."""

def classify(n):
    return "even" if n % 2 == 0 else "odd"

def accuracy(values):
    return sum(classify(n)==label for n,label in values)/len(values) if values else 0.0
''',
"benchmarks/maze_seed.py":'''"""Seeded maze coordinate generator used for reproducible benchmarks."""
import random

def sample_cells(width,height,seed=0,count=16):
    rng=random.Random(seed)
    cells=[(x,y) for y in range(height) for x in range(width)]
    rng.shuffle(cells)
    return cells[:min(count,len(cells))]
'''
}

def main():
    ap=argparse.ArgumentParser()
    ap.add_argument("--seed",type=int,default=20261010)
    ap.add_argument("--output",default="generated")
    args=ap.parse_args()
    rng=random.Random(args.seed)
    root=Path(args.output)
    root.mkdir(parents=True,exist_ok=True)
    for rel,content in TEMPLATES.items():
        path=root/rel
        path.parent.mkdir(parents=True,exist_ok=True)
        path.write_text(content,encoding="utf-8")
    manifest={
        "generator_seed":args.seed,
        "generated_files":sorted(TEMPLATES),
        "random_state_sample":rng.getrandbits(32),
        "status":"generated"
    }
    (root/"experiments").mkdir(exist_ok=True)
    (root/"experiments/manifest.json").write_text(
        json.dumps(manifest,indent=2)+"\n",encoding="utf-8")
    print(f"generated {len(TEMPLATES)+1} files with seed {args.seed}")

if __name__=="__main__":
    main()
